import { MeshBasicNodeMaterial, PlaneGeometry, Mesh, Group, Color, DoubleSide } from 'three/webgpu';
import { texture, uv, vec3, vec4, mix, smoothstep, float, fract, dot, hash, time, uniform } from 'three/tsl';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const THREE = ctx.THREE;
  const group = new Group();
  group.name = 'feature-card-1';

  // ---- palette (exact spec) ----
  const ink = new THREE.Color('#16161d');
  const paper = new THREE.Color('#e8ecf2');
  const accent = new THREE.Color('#ff2a38');
  const surface = new THREE.Color('#0b0b10');

  // source rect 512x320 -> aspect 1.6:1
  const aspect = 512 / 320;
  const w = 1.7;
  const h = w / aspect;

  // ---- main textured plane (card face) ----
  const geo = new PlaneGeometry(w, h, 1, 1);
  const mat = new MeshBasicNodeMaterial({
    transparent: true,
    side: DoubleSide,
    toneMapped: false,
  });
  mat.color = surface.clone();

  // placeholder engineered gradient while texture loads (vertical ink -> surface)
  const uvNode = uv();
  const gradT = uvNode.y.oneMinus();
  const placeholder = mix(
    vec3(ink.r, ink.g, ink.b),
    vec3(surface.r * 1.4, surface.g * 1.4, surface.b * 1.6),
    smoothstep(0.0, 1.0, gradT)
  );

  // subtle film grain via hash noise
  const g = hash(uvNode.mul(vec3(800.0, 500.0, 1.0)).xy);
  const grain = g.sub(0.5).mul(0.04);

  // accent hairline at top edge (signal red) — <=10% of frame
  const topEdge = smoothstep(0.97, 0.99, uvNode.y).mul(0.9);

  // texUniform slot — filled when loaded
  const texUniform = uniform(null);

  const texColor = texture(texUniform, uvNode);
  const composed = mix(
    placeholder.add(grain),
    texColor.rgb.add(grain.mul(0.5)),
    smoothstep(0.0, 1.0, float(0.0).oneMinus()) // 0 until tex present
  );

  // We can't easily branch on null uniform in TSL; instead we swap output via a presence flag uniform.
  const hasTex = uniform(0.0);
  const finalColor = mix(
    placeholder.add(grain),
    texColor.rgb.add(grain.mul(0.4)),
    hasTex
  ).add(vec3(topEdge * accent.r, topEdge * accent.g, topEdge * accent.b));

  mat.colorNode = finalColor;

  const plane = new Mesh(geo, mat);
  plane.renderOrder = 2;
  group.add(plane);

  // ---- contact shadow under card ----
  const shadowGeo = new PlaneGeometry(w * 1.5, h * 0.5);
  const shadowMat = new MeshBasicNodeMaterial({
    transparent: true,
    depthWrite: false,
    opacity: 0.5,
    toneMapped: false,
  });
  shadowMat.color = new THREE.Color(0x000000);
  const sUV = uv();
  const sRad = sUV.sub(0.5).length();
  const sAlpha = smoothstep(0.5, 0.0, sRad).mul(0.55);
  shadowMat.colorNode = vec4(0.0, 0.0, 0.0, sAlpha);
  shadowMat.opacityNode = sAlpha;
  const shadow = new Mesh(shadowGeo, shadowMat);
  shadow.position.set(0, -h * 0.55, -0.02);
  shadow.rotation.x = -0.18;
  group.add(shadow);

  // ---- load texture (async, cached) ----
  const url = config.imageUrl;
  if (url) {
    ctx.textureLoader.loadTexture(url).then((tex) => {
      tex.colorSpace = THREE.SRGBColorSpace;
      tex.anisotropy = 4;
      texUniform.value = tex;
      hasTex.value = 1.0;
      mat.needsUpdate = true;
    });
  }

  // ---- subtle weighted-settle entrance (no primitive requested) ----
  const tl = gsap.timeline();
  group.scale.set(0.96, 0.96, 0.96);
  group.userData.visible = true;
  tl.fromTo(
    group.position,
    { z: 0.4 },
    { z: 0, duration: 0.7, ease: 'power3.out' },
    0
  ).to(
    group.scale,
    { x: 1.0, y: 1.0, z: 1.0, duration: 0.9, ease: 'power4.out' },
    0
  ).fromTo(
    mat,
    { opacity: 0.0 },
    { opacity: 1.0, duration: 0.6, ease: 'power2.out' },
    0
  );

  // ---- handlers (none required by spec; keep bus surface) ----
  group.userData.handlers = {
    click: () => {},
    hover: () => {},
  };

  // ---- cleanup ----
  const disposables = [geo, mat, shadowGeo, shadowMat];
  group.userData.cleanup = () => {
    tl.kill();
    for (const d of disposables) {
      try { d.dispose(); } catch (e) {}
    }
    const t = texUniform.value;
    if (t && t.dispose) { try { t.dispose(); } catch (e) {} }
  };

  return group;
}
